const express = require('express');
const Piscina = require('piscina');
const path = require('path');
const { verifySession } = require('../auth');
const MediaAsset = require('../models/MediaAsset');

const app = express();
app.use(express.json());

const redactionPool = new Piscina({
  filename: path.resolve(__dirname, '../workers/faceRedactionWorker.js'),
  maxThreads: 4
});

app.post('/api/media/redact', verifySession, async (req, res) => {
  const { mediaAssetId, blurRadius } = req.body;

  const asset = await MediaAsset.findOne({
    _id: mediaAssetId,
    organizationId: req.session.organizationId
  });
  if (!asset) {
    return res.status(403).json({ error: 'Forbidden: media asset not found or unauthorized' });
  }

  const output = await redactionPool.run({
    assetId: mediaAssetId,
    radius: blurRadius || 15
  });

  res.json({ status: 'redaction_complete', modifiedAssetId: output.newAssetId });
});
